package vn.covie.outbox.application; import java.time.Duration; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component;
@Component public class OutboxRetryPolicy { private final int maxAttempts; private final long initial; private final long maximum; public OutboxRetryPolicy(@Value("${covie.outbox.max-attempts:10}")int max,@Value("${covie.outbox.initial-backoff-seconds:1}")long initial,@Value("${covie.outbox.max-backoff-seconds:300}")long maximum){this.maxAttempts=max;this.initial=initial;this.maximum=maximum;} public int maxAttempts(){return maxAttempts;} public Duration delayForAttempt(int attempt){if(attempt<1)throw new IllegalArgumentException("attempt must be positive");long multiplier=1L<<Math.min(attempt-1,20);return Duration.ofSeconds(Math.min(maximum,Math.multiplyExact(initial,multiplier)));}}
